<script setup lang="ts">export type BottomItem={id:string;label:string;icon?:string;disabled?:boolean};defineProps<{items:BottomItem[];modelValue:string}>();const emit=defineEmits<{'update:modelValue':[id:string];select:[id:string]}>()</script><template><nav class="vx-bottomnav" aria-label="Mobile navigation"><button v-for="item in items" :key="item.id" type="button" :disabled="item.disabled" :aria-current="modelValue===item.id?'page':undefined" @click="emit('update:modelValue',item.id);emit('select',item.id)"><span aria-hidden="true">{{item.icon||'•'}}</span><small>{{item.label}}</small></button></nav></template>
